//! Jeffrey A. Hirsch & John L. Person, Commodity Trader's Almanac 2010 (4th ed.; drive folder says 2008).
//! The seasonal trades (Top Percentage Plays, printed p.126-127) are exact calendar rules: enter on the
//! Nth trading day of a month, hold a fixed number of trading days. Only the four S&P 500 futures trades
//! can run on data the vault has (SPX/NIFTY as the index swap of the S&P futures); every other trade needs
//! the front-month/next-month futures contract history -> NeedsData. Page refs are printed pages.
//! Sources and checks: library/hcta/.
use crate::connors::{claim, Ctx, Leg, ParamDef, Params, Status, StrategyDef, Trade};

pub const BOOK: &str = "hcta";
/// Admitted 2026-10-24 (authors/person/admission/SOURCE-CONTRACT.md): the four S&P 500 calendar trades on indices, ETFs and
/// stocks (US and India) as a declared application; independent ledgers, 0 mismatches. Futures trades stay NeedsData.
pub const REVIEWED: &[&str] = &["hcta_sp_jan_long", "hcta_sp_apr_long", "hcta_sp_jul_short", "hcta_sp_oct_long"];
pub fn reviewed(id: &str) -> bool { REVIEWED.contains(&id) }
const FUT: &str = "the named futures contract's daily history (continuously linked, non-adjusted front/next-month contracts as in the book); the vault has no futures data";

