pub fn params(id: &str) -> Option<Vec<ParamDef>> {
    let &(_, _, td, hold, _) = TRADES.iter().find(|t| t.0 == id)?;
    Some(vec![
        ParamDef { key: "td", label: "Enter on the Nth trading day of the month", def: td, min: 1., max: 23., step: 1. },
        ParamDef { key: "hold", label: "Hold (trading days after entry)", def: hold, min: 1., max: 200., step: 1. },
    ])
}

fn ym(s: &str) -> (i64, u32) {
    (s[0..4].parse().unwrap_or(0), s[5..7].parse().unwrap_or(0))
}

/// Enter at the close of the month's Nth trading day; exit at the close `hold` trading days later
/// (the hold count starts the day after the purchase). One position at a time.
pub fn run(id: &str, x: &Ctx, from: usize, to: usize, p: &Params) -> Option<Vec<Trade>> {
    let &(_, month, td0, hold0, dir) = TRADES.iter().find(|t| t.0 == id)?;
    let n = x.r.len();
    if n == 0 || from > to || to >= n {
        return Some(vec![]);
    }
    let td = p.get("td").copied().unwrap_or(td0).round().max(1.0) as usize;
    let hold = p.get("hold").copied().unwrap_or(hold0).round().max(1.0) as usize;
    let mut out: Vec<Trade> = vec![];
    for f in 1..n {
        if ym(&x.r[f].date) == ym(&x.r[f - 1].date) || ym(&x.r[f].date).1 != month {
            continue; // f = first trading day of the trade month
        }
        let e = f + td - 1;
        if e >= n || ym(&x.r[e].date) != ym(&x.r[f].date) || e < from || e > to || out.last().is_some_and(|t| e < t.exit_i) {
            continue;
        }
        let xi = e + hold;
        let mut t = Trade { dir, legs: vec![Leg { i: e, px: x.c[e], w: 1.0 }], exit_i: xi, exit_px: f64::NAN, reason: format!("{hold} trading days held · close"),
            entry_kind: "close", signal_i: xi, open: false, exits: vec![] };
        if xi <= to {
            t.exit_px = x.c[xi];
        } else {
            (t.exit_i, t.exit_px, t.signal_i, t.open, t.reason) = (to, x.c[to], to, true, "open".into());
        }
        out.push(t);
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Row;
    #[test]
    fn nth_trading_day_entry_and_hold_count_start_the_day_after() {
        // January 1983: the 15th trading day is the 21st; 7 days later is Feb 1 (book p.20 first row)
        let days = ["1982-12-31", "1983-01-03", "1983-01-04", "1983-01-05", "1983-01-06", "1983-01-07", "1983-01-10", "1983-01-11", "1983-01-12", "1983-01-13",
            "1983-01-14", "1983-01-17", "1983-01-18", "1983-01-19", "1983-01-20", "1983-01-21", "1983-01-24", "1983-01-25", "1983-01-26", "1983-01-27",
            "1983-01-28", "1983-01-31", "1983-02-01", "1983-02-02"];
        let r: Vec<Row> = days.iter().map(|d| Row { ticker: "T".into(), date: d.to_string(), open: 1., high: 1., low: 1., close: 1., volume: None }).collect();
        let x = Ctx::new(&r, &r, &[]);
        let t = run("hcta_sp_jan_long", &x, 0, r.len() - 1, &Params::new()).unwrap();
        assert_eq!(t.len(), 1);
        assert_eq!((x.r[t[0].legs[0].i].date.as_str(), x.r[t[0].exit_i].date.as_str()), ("1983-01-21", "1983-02-01"));
    }
}
